package com.sunrise.dentalclinic.controller;
import com.sunrise.dentalclinic.dto.AppointmentRequest;import com.sunrise.dentalclinic.service.*;import jakarta.validation.Valid;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.validation.BindingResult;import org.springframework.web.bind.annotation.*;import org.springframework.web.servlet.mvc.support.RedirectAttributes;
@Controller @RequestMapping("/appointments") public class AppointmentController{private final AppointmentService service;private final PatientService patients;private final DentistService dentists;private final TreatmentService treatments;public AppointmentController(AppointmentService s,PatientService p,DentistService d,TreatmentService t){service=s;patients=p;dentists=d;treatments=t;}@GetMapping String list(@RequestParam(required=false)String number,Model m){m.addAttribute("appointments",number==null||number.isBlank()?service.all():java.util.List.of(service.byNumber(number)));m.addAttribute("number",number);return "appointments/list";}@GetMapping("/new")String create(Model m){m.addAttribute("appointmentRequest",new AppointmentRequest(null,null,null,null,null,""));options(m);return "appointments/form";}@PostMapping String save(@Valid @ModelAttribute AppointmentRequest appointmentRequest,BindingResult e,Model m,RedirectAttributes r){if(e.hasErrors()){options(m);return "appointments/form";}var a=service.create(appointmentRequest);r.addFlashAttribute("success","Appointment registered");return "redirect:/appointments/"+a.getId();}@GetMapping("/{id}")String view(@PathVariable Long id,Model m){m.addAttribute("appointment",service.get(id));return "appointments/view";}@GetMapping("/{id}/edit")String edit(@PathVariable Long id,Model m){var a=service.get(id);m.addAttribute("appointment",a);m.addAttribute("appointmentRequest",new AppointmentRequest(a.getPatient().getId(),a.getDentist().getId(),a.getTreatment().getId(),a.getAppointmentDate(),a.getAppointmentTime(),a.getNotes()));options(m);return "appointments/form";}@PostMapping("/{id}")String update(@PathVariable Long id,@Valid @ModelAttribute AppointmentRequest appointmentRequest,BindingResult e,Model m){if(e.hasErrors()){m.addAttribute("appointment",service.get(id));options(m);return "appointments/form";}service.update(id,appointmentRequest);return "redirect:/appointments/"+id;}@PostMapping("/{id}/cancel")String cancel(@PathVariable Long id){service.cancel(id);return "redirect:/appointments/"+id;}@PostMapping("/{id}/complete")String complete(@PathVariable Long id){service.complete(id);return "redirect:/appointments/"+id;}private void options(Model m){m.addAttribute("patients",patients.search(null));m.addAttribute("dentists",dentists.active());m.addAttribute("treatments",treatments.active());}}
